public class LogPurgeJob implements Schedulable, Database.Batchable<sObject> {

    /**
     * No-argument constructor as required.
     */
    public LogPurgeJob() {
    }

    /**
     * Schedulable execute method. 
     * Starts the batch job to perform the purge.
     * 
     * @param sc The context of the scheduled job.
     */
    public void execute(SchedulableContext sc) {
        Database.executeBatch(new LogPurgeJob());
    }

    /**
     * Batch start method.
     * Defines the scope of records to be purged based on the retention policy.
     * 
     * @param bc The context of the batch job.
     * @return A QueryLocator containing the records to be deleted.
     */
    public Database.QueryLocator start(Database.BatchableContext bc) {
        DateTime thirtyDaysAgo = DateTime.now().addDays(-30);
        DateTime oneEightyDaysAgo = DateTime.now().addDays(-180);

        // Retention Policy:
        // 1. Records where Level__c is not 'ERROR' (including null) are purged after 30 days.
        // 2. Records where Level__c is 'ERROR' are purged after 180 days.
        //
        // In SOQL, 'CreatedDate < :timestamp' identifies records older than the specified time.
        // Note: 'Level__c != 'ERROR'' in SOQL does not include records where Level__c is null,
        // so we explicitly include 'Level__c = null'.
        return Database.getQueryLocator([
            SELECT Id 
            FROM FB_Integration_Log__c 
            WHERE (Level__c != 'ERROR' OR Level__c = null) AND CreatedDate < :thirtyDaysAgo
            OR (Level__c = 'ERROR' AND CreatedDate < :oneEightyDaysAgo)
        ]);
    }

    /**
     * Batch execute method.
     * Deletes the records in the current scope.
     * 
     * @param bc The context of the batch job.
     * @param scope The list of records to be processed in this batch.
     */
    public void execute(Database.BatchableContext bc, List<FB_Integration_Log__c> scope) {
        if (!scope.isEmpty()) {
            // Using Database.delete with allOrNone=false to ensure that a single record 
            // lock (common in high-volume integration logs) doesn't cause the entire 
            // batch to fail, which is a production best practice for cleanup jobs.
            Database.delete(scope, false);
        }
    }

    /**
     * Batch finish method.
     * 
     * @param bc The context of the batch job.
     */
    public void finish(Database.BatchableContext bc) {
        // No post-processing required.
    }

    /**
     * Schedules the job to run every day at 02:00.
     * 
     * @return The Id of the scheduled job.
     */
    public static Id scheduleNightly() {
        // Cron expression for 02:00:00 AM every day: 
        // Seconds Minutes Hours DayOfMonth Month DayOfWeek
        String cronExp = '0 0 2 * * ?';
        return System.schedule('Log purge (nightly)', cronExp, new LogPurgeJob());
    }
}
