public class LogPurgeJob implements Schedulable, Database.Batchable<sObject> {

    /**
     * No-argument constructor as required by the implementation.
     */
    public LogPurgeJob() {}

    /**
     * Implementation of Schedulable.execute.
     * Starts a batch job to handle the deletion of logs in a bulk-safe manner.
     * 
     * @param sc The schedulable context.
     */
    public void execute(SchedulableContext sc) {
        Database.executeBatch(new LogPurgeJob());
    }

    /**
     * Implementation of Database.Batchable.start.
     * Queries for records that exceed their retention periods:
     * - ERROR logs: kept for 180 days.
     * - All other logs (including blank Level__c): kept for 30 days.
     *
     * @param bc The batchable context.
     * @return A QueryLocator for the records to be deleted.
     */
    public Database.QueryLocator start(Database.BatchableContext bc) {
        DateTime thirtyDaysAgo = System.now().addDays(-30);
        DateTime oneEightyDaysAgo = System.now().addDays(-180);

        // In SOQL, 'field != value' excludes nulls. 
        // To include blanks/nulls in the 30-day rule, we explicitly check for Level__c = null.
        return Database.getQueryLocator([
            SELECT Id 
            FROM FB_Integration_Log__c 
            WHERE (Level__c = 'ERROR' AND CreatedDate < :oneEightyDaysAgo)
               OR ((Level__c != 'ERROR' OR Level__c = null) AND CreatedDate < :thirtyDaysAgo)
        ]);
    }

    /**
     * Implementation of Database.Batchable.execute.
     * Deletes the records processed in the current batch.
     *
     * @param bc The batchable context.
     * @param scope The list of records to process.
     */
    public void execute(Database.BatchableContext bc, List<FB_Integration_Log__c> scope) {
        if (!scope.isEmpty()) {
            delete scope;
        }
    }

    /**
     * Implementation of Database.Batchable.finish.
     *
     * @param bc The batchable context.
     */
    public void finish(Database.BatchableContext bc) {
        // Post-batch processing not required for this task.
    }

    /**
     * Schedules the purge job to run every day at 02:00 AM.
     *
     * @return The Id of the newly scheduled job.
     */
    public static Id scheduleNightly() {
        String jobName = 'Log purge (nightly)';
        // Cron expression for 02:00:00 AM every day: "0 0 2 * * ?"
        String cronExp = '0 0 2 * * ?';
        return System.schedule(jobName, cronExp, new LogPurgeJob());
    }
