            if (key === 'ArrowDown') {
                if (this.activeIndex < this._options.length - 1) {
                    this.activeIndex++;
                }
            } else if (key === 'ArrowUp') {
                if (this.activeIndex > 0) {
                    this.activeIndex--;
                }
            } else if (key === 'Home') {
                this.activeIndex = 0;
            } else if (key === 'End') {
                this.activeIndex = this._options.length - 1;
            } else if (key === 'Enter' || key === ' ') {
                const selectedValue = this._options[this.activeIndex]?.value;
                if (selectedValue !== undefined) {
                    this.handleSelect(selectedValue);
                }
            }
        }
