        if (!this.options || this.options.length === 0) {
            this.activeOptionIndex = -1;
            return;
        }

        const index = this.options.findIndex(opt => opt.value === this.value);
        if (index !== -1) {
            this.activeOptionIndex = index;
        } else {
            // The active option starts as the selected option, or the first option if nothing is selected.
            this.activeOptionIndex = 0;
        }
    }

    connectedCallback() {
        this.updateActiveOptionIndex();
    }

    handleKeyDown(event) {
        let moved = false;
        const { key } = event;

        switch (key) {
            case 'ArrowDown':
                if (this.activeOptionIndex < this.options.length - 1) {
                    this.activeOptionIndex++;
                }
                moved = true;
                break;
            case 'ArrowUp':
                if (this.activeOptionIndex > 0) {
                    this.activeOptionIndex--;
                }
                moved = true;
                break;
            case 'Home':
                this.activeOptionIndex = 0;
                moved = true;
                break;
            case 'End':
                this.activeOptionIndex = this.options.length - 1;
                moved = true;
                break;
            case 'Enter':
            case ' ':
                this.selectOption(this.activeOptionIndex);
                moved = true;
                break;
            default:
                return;
        }

        if (moved) {
            event.preventDefault();
        }
    }

    handleOptionClick(event) {
        const val = event.currentTarget.dataset.value;
        // Find index using string comparison to handle potential type mismatch from DOM attributes
        const index = this.options.findIndex(opt => String(opt.value) === val);
        if (index !== -1) {
            this.selectOption(index);
        }
    }

    selectOption(index) {
        if (index < 0 || index >= this.options.length) return;

        const newValue = this.options[index].value;

        // Clicking an option selects it and makes it the active option.
        this.activeOptionIndex = index;

        if (newValue !== this.value) {
            this.dispatchEvent(new CustomEvent('change', {
                detail: { value: newValue }
            }));
        }
    }
